\title[Sharp Small Ramsey Numbers and a Parity Obstruction]{Sharp Small Ramsey
Numbers and a Parity Obstruction:\\ $R(3,3)=6$, $R(3,4)=9$, the
Erd\H{o}s--Szekeres Bound, and Probabilistic Lower Bounds}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\begin{abstract}
We develop, from first principles, the elementary theory of finite two-colour
Ramsey numbers and establish three sharp facts together with the structural
machinery behind them. Working with the \emph{arrow relation} $n \Arr (s,t)$ ---
every red/blue colouring of a complete graph on $\ge n$ vertices contains a red
$s$-clique or a blue $t$-clique --- we prove the Erd\H{o}s--Szekeres binomial
ceiling $R(s{+}1,t{+}1) \le \binom{s+t}{s}$ via a clean recursive step, and we
determine two exact values: $R(3,3)=6$ (with the pentagon as extremal colouring)
and $R(3,4)=9$ (with a M\"obius-ladder circulant as the extremal colouring on
eight vertices). The upper bound $R(3,4) \le 9$ strictly improves the binomial
prediction of $10$, and we trace this improvement to a single arithmetic
phenomenon: a handshake-parity obstruction. We isolate that phenomenon as two
reusable theorems on arbitrary finite vertex sets --- that the red-degrees inside
an odd-order set cannot all be odd, and equivalently that no $d$-regular red
colouring exists on $n$ vertices when $nd$ is odd. Finally, we record the
first-moment probabilistic lower bound for $r$-uniform hypergraph Ramsey numbers,
which for graphs yields $R(k,k) > 2^{k/2}$ and frames the classical exponential
sandwich $2^{k/2} < R(k,k) \le 4^k$. All results are formally verified.
\end{abstract}
\maketitle

\section{Introduction}
Ramsey theory quantifies the principle that sufficiently large combinatorial
structures cannot be entirely disordered. The two-colour graph Ramsey number
$R(s,t)$ is the least $n$ such that every $2$-colouring of the edges of the
complete graph $K_n$ contains a red clique on $s$ vertices or a blue clique on
$t$ vertices. Three foundational themes organise the classical theory:
\begin{enumerate}
  \item \textbf{Upper bounds by recursion.} The Erd\H{o}s--Szekeres argument
  yields the binomial ceiling $R(s{+}1,t{+}1) \le \binom{s+t}{s}$.
  \item \textbf{Exact small values.} The first nontrivial values, $R(3,3)=6$ and
  $R(3,4)=9$, require matching constructions and combinatorial obstructions. For
  $R(3,4)$ the binomial ceiling is not tight, and an extra parity argument is
  needed.
  \item \textbf{Lower bounds by the probabilistic method.} A first-moment
  computation gives exponential lower bounds --- for graphs, $R(k,k) > 2^{k/2}$.
\end{enumerate}
We present a self-contained treatment of all three, emphasising the structural
reason $R(3,4)=9$ beats its binomial ceiling, which we extract into a general
\emph{parity obstruction}.

Throughout, a two-colouring of a complete graph on a vertex set $V$ is encoded by
a single graph $G$ on $V$: edges of $G$ are \textbf{red} and edges of its
complement $G^{\compl}$ are \textbf{blue}.

\section{The arrow relation and monotonicity}
\begin{definition}[Arrow relation]
For naturals $n,s,t$, write $n \Arr (s,t)$ to mean: for every type $V$ with
decidable equality, every graph $G$ on $V$, and every finite $W \subseteq V$ with
$|W| \ge n$, there is $S \subseteq W$ inducing a red $s$-clique (a clique of $G$),
or there is $S \subseteq W$ inducing a blue $t$-clique (a clique of $G^{\compl}$).
The Ramsey number is $R(s,t) = \min\{n : n \Arr (s,t)\}$.
\end{definition}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $n \Arr (s,t)$ and $n \le n'$, then $n' \Arr (s,t)$.
\end{lemma}
\begin{proof}
Any $W$ with $|W| \ge n'$ has $|W| \ge n$, so the hypothesis applies.
\end{proof}

\begin{lemma}[Base cases]\label{lem:base}
For all $a,b$, $1 \Arr (1,b)$ and $1 \Arr (a,1)$.
\end{lemma}
\begin{proof}
A nonempty $W$ contains a vertex $v$; the singleton $\{v\}$ is both a red and a
blue $1$-clique.
\end{proof}

\section{The Erd\H{o}s--Szekeres recursion and binomial bound}
\begin{lemma}[Erd\H{o}s--Szekeres step]\label{lem:step}
If $m>0$, $n>0$, $m \Arr (s,t{+}1)$ and $n \Arr (s{+}1,t)$, then $(m+n) \Arr
(s{+}1,t{+}1)$.
\end{lemma}
\begin{proof}
Let $|W| \ge m+n$ and fix $v \in W$. Partition $W \setminus \{v\}$ into red
neighbours $R$ and blue neighbours $B$ of $v$, so $|R|+|B| = |W|-1 \ge m+n-1$;
hence $|R| \ge m$ or $|B| \ge n$. If $|R| \ge m$, apply $m \Arr (s,t{+}1)$ inside
$R$: either a blue $(t{+}1)$-clique (done) or a red $s$-clique $S \subseteq R$,
and since every vertex of $R$ is red-adjacent to $v \notin S$, the set $S \cup
\{v\}$ is a red $(s{+}1)$-clique. The case $|B| \ge n$ is symmetric.
\end{proof}

\begin{theorem}[Binomial bound]\label{thm:binom}
For all $s,t$, $\binom{s+t}{s} \Arr (s{+}1,t{+}1)$; equivalently $R(s{+}1,t{+}1)
\le \binom{s+t}{s}$.
\end{theorem}
\begin{proof}
Double induction on $s,t$ with base cases from Lemma~\ref{lem:base}. The
inductive step combines the two smaller instances via Lemma~\ref{lem:step}, the
cardinalities adding by Pascal's rule $\binom{s+t}{s} = \binom{(s-1)+t}{s-1} +
\binom{s+(t-1)}{s}$.
\end{proof}
In particular $R(k{+}1,k{+}1) \le \binom{2k}{k} < 4^k$.

\section{The exact value $R(3,3)=6$}
\begin{theorem}[Upper bound]\label{thm:33up}
$6 \Arr (3,3)$.
\end{theorem}
\begin{proof}
The instance $s=t=2$ of Theorem~\ref{thm:binom}, since $\binom{4}{2}=6$.
\end{proof}

\begin{definition}[Pentagon]
Let $C_5$ be the graph on $\mathbb{Z}/5$ with $a \sim b$ iff $a+1=b$ or $b+1=a$.
\end{definition}

\begin{lemma}\label{lem:pent}
$C_5$ has no $3$-clique, and its complement $C_5^{\compl}$ (again a $5$-cycle)
has no $3$-clique.
\end{lemma}
\begin{proof}
Finite verification over the $\binom{5}{3}=10$ triples.
\end{proof}

\begin{theorem}[Lower bound]\label{thm:33low}
$\lnot\,(5 \Arr (3,3))$.
\end{theorem}
\begin{proof}
The pentagon colouring of $K_5$ has neither a red nor a blue triangle by
Lemma~\ref{lem:pent}.
\end{proof}

\begin{theorem}\label{thm:33}
$6 \Arr (3,3)$ and $\lnot\,(5 \Arr (3,3))$; that is, $R(3,3)=6$.
\end{theorem}

\section{The exact value $R(3,4)=9$}
The binomial ceiling gives only $R(3,4) \le \binom{5}{2}=10$. We establish the
exact value $9$ in two parts.

\subsection{Lower bound: the M\"obius ladder}
On $\mathbb{Z}/8$, declare $a \sim b$ red iff their difference lies in $\{\pm
1,4\}$ --- the M\"obius ladder circulant $C_8(1,4)$. This red graph is
triangle-free and its blue complement has no $4$-clique, so $8 \not\Arr (3,4)$
and $R(3,4) > 8$. (Finite verification over $\mathbb{Z}/8$.)

\subsection{Upper bound via the handshake lemma}
\begin{lemma}[Handshake parity]\label{lem:handshake}
For any graph $G$ and finite $W$,
\[
\sum_{v \in W} \bigl|\{\, w \in W \setminus \{v\} : v \sim_G w \,\}\bigr|
\quad\text{is even.}
\]
\end{lemma}
\begin{proof}
The sum counts ordered red pairs $(v,w)$ inside $W$; the swap $(v,w) \mapsto
(w,v)$ is a fixed-point-free involution (no loops), so the count is even.
Equivalently, the sum equals $2\,|E_{\mathrm{red}}(W)|$.
\end{proof}

\begin{theorem}[Upper bound]\label{thm:34up}
$9 \Arr (3,4)$.
\end{theorem}
\begin{proof}
Suppose a colouring of a $9$-vertex set $W$ has no red triangle and no blue
$K_4$. If a vertex had red-degree $\ge 4$, four red neighbours would contain a
red edge (red triangle) or be pairwise blue (blue $K_4$). If a vertex had
red-degree $\le 2$, its $\ge 6$ blue neighbours would contain a monochromatic
triangle by $6 \Arr (3,3)$, escalating to a forbidden configuration. Hence every
red-degree is exactly $3$, making the red graph $3$-regular on $9$ vertices, with
degree sum $9\cdot 3 = 27$ odd --- contradicting Lemma~\ref{lem:handshake}.
\end{proof}

\begin{theorem}\label{thm:34}
$9 \Arr (3,4)$ and $\lnot\,(8 \Arr (3,4))$; that is, $R(3,4)=9$.
\end{theorem}

\section{The parity obstruction in full generality}
\begin{definition}[Red-degree inside a set]
For a graph $G$, finite $W$, and vertex $v$,
\[
\redDeg_G(W,v) = \bigl|\{\, w \in W \setminus \{v\} : v \sim_G w \,\}\bigr|.
\]
\end{definition}

\begin{theorem}[Regularity--parity obstruction]\label{thm:parity}
Let $G$ be any graph and $W$ finite with $|W|$ odd. Then it is not the case that
$\redDeg_G(W,v)$ is odd for every $v \in W$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:handshake} the sum $S = \sum_{v \in W} \redDeg_G(W,v)$ is even.
If every summand were odd, $S$ would be a sum of an odd number ($|W|$) of odd
terms, hence odd --- a contradiction.
\end{proof}

\begin{theorem}[No odd-regular colouring]\label{thm:noreg}
Let $G$ be any graph, $|W| = n$, and suppose $n\cdot d$ is odd. Then it is not
the case that $\redDeg_G(W,v) = d$ for every $v \in W$.
\end{theorem}
\begin{proof}
Since $nd$ is odd, both $n$ and $d$ are odd. If every red-degree equalled $d$,
then $|W|=n$ is odd and all red-degrees are odd, contradicting
Theorem~\ref{thm:parity}.
\end{proof}
The bound $R(3,4) \le 9$ is exactly Theorem~\ref{thm:noreg} with $(n,d)=(9,3)$.

\section{Probabilistic lower bounds}
We state the first-moment bound for $r$-uniform hypergraphs: a colouring assigns
red/blue to each $r$-subset, and a monochromatic $k$-clique is a $k$-set all of
whose $r$-subsets share a colour. Write $\mathrm{HRP}(r,n,k,k)$ for the
corresponding $r$-uniform arrow property on $n$ vertices.

\begin{theorem}[First-moment lower bound]\label{thm:prob}
Let $2 \le r \le k \le n$. If $2\binom{n}{k} < 2^{\binom{k}{r}}$, then
$\lnot\,\mathrm{HRP}(r,n,k,k)$; equivalently the Ramsey number exceeds $n$.
\end{theorem}
\begin{proof}
Average over the $2^{\binom{n}{r}}$ colourings. For a fixed $k$-set $T$, the
number of colourings making $T$ monochromatic is $2\cdot 2^{\binom{n}{r} -
\binom{k}{r}}$. Summing over the $\binom{n}{k}$ candidate sets,
\[
\sum_{|T|=k} \bigl|\{c : T \text{ monochromatic}\}\bigr|
\le 2\binom{n}{k}\,2^{\binom{n}{r}-\binom{k}{r}} < 2^{\binom{n}{r}},
\]
so some colouring has no monochromatic $k$-clique.
\end{proof}

\begin{corollary}[Graph case]
With $r=2$, $\binom{k}{2}=k(k-1)/2$, the threshold holds up to $n \approx
2^{k/2}$, giving $R(k,k) > 2^{k/2}$. With Theorem~\ref{thm:binom} this yields the
sandwich $2^{k/2} < R(k,k) < 4^k$. For general $r$, $\binom{k}{r}=\Theta(k^r)$
gives $R_r(k,k) > 2^{\Omega(k^{r-1})}$.
\end{corollary}

\section{Algorithms}
\textbf{(A) Binomial ceiling}: tabulate $U(s,t) = U(s-1,t)+U(s,t-1)$ with
$U(1,t)=U(s,1)=1$, returning $\binom{s+t-2}{s-1}$ in $O(st)$.
\textbf{(B) Clique certifier}: search an explicit colouring for a red $s$-clique
or blue $t$-clique; certifies the pentagon and M\"obius-ladder lower bounds.
\textbf{(C) Parity checker}: flag infeasibility when $|W|$ is odd and all degrees
odd (Theorems~\ref{thm:parity}--\ref{thm:noreg}).
\textbf{(D) First-moment threshold}: return the largest $n$ with $2\binom{n}{k} <
2^{\binom{k}{r}}$ (Theorem~\ref{thm:prob}).

\section{Applications and discussion}
Ramsey guarantees underpin error-correcting codes, fault-tolerant network
design, complexity lower bounds, and the analysis of large networks. The
distinctive methodological message here is that the gap between $R(3,4)\le 10$
and $R(3,4)=9$ is closed by a single arithmetic invariant; promoting the
``$27$ is odd'' step to Theorems~\ref{thm:parity}--\ref{thm:noreg} makes the
obstruction portable.

\section{Future work}
General even-pair sharpening $R(s,t) \le R(s-1,t)+R(s,t-1)-1$ when both
summands are even; $R(3,5)=14$ via the same regular-obstruction route;
sharpness of the base $\sqrt2$ in the first-moment lower bound; and the
prediction that extremal colourings live on the ``permitted'' side ($nd$ even)
of Theorem~\ref{thm:noreg}.

