"""Exhaustively certify R(3,3) = 6 over all 2^15 colourings of K_6."""
from itertools import combinations
from typing import Dict, FrozenSet, Iterable, List

Edge = FrozenSet[int]
Coloring = Dict[Edge, bool]


def circulant(n: int, diffs: Iterable[int]) -> Coloring:
    dset = set()
    for d in diffs:
        dset.add(d % n); dset.add((-d) % n)
    return {frozenset((a, b)): ((a - b) % n in dset) for a, b in combinations(range(n), 2)}


def has_mono(col: Coloring, n: int, size: int, red: bool) -> bool:
    return any(all(col[frozenset((a, b))] == red for a, b in combinations(S, 2))
               for S in combinations(range(n), size))


def arrows(col: Coloring, n: int, s: int, t: int) -> bool:
    return has_mono(col, n, s, True) or has_mono(col, n, t, False)


def main() -> None:
    edges: List[Edge] = [frozenset(e) for e in combinations(range(6), 2)]
    m = len(edges)
    upper = all(
        arrows({edges[i]: bool((mask >> i) & 1) for i in range(m)}, 6, 3, 3)
        for mask in range(2 ** m)
    )
    pentagon = circulant(5, [1])
    lower = not arrows(pentagon, 5, 3, 3)
    print(f"every K_6 colouring arrows (3,3): {upper}")
    print(f"pentagon on K_5 avoids (3,3)    : {lower}")
    print(f"=> R(3,3) = 6 certified: {upper and lower}")


if __name__ == "__main__":
    main()

"""Certify R(3,4) = 9: Mobius-ladder lower bound + handshake-parity upper bound."""
from itertools import combinations
from typing import Dict, FrozenSet, Iterable, List

Edge = FrozenSet[int]
Coloring = Dict[Edge, bool]


def circulant(n: int, diffs: Iterable[int]) -> Coloring:
    dset = set()
    for d in diffs:
        dset.add(d % n); dset.add((-d) % n)
    return {frozenset((a, b)): ((a - b) % n in dset) for a, b in combinations(range(n), 2)}


def has_mono(col: Coloring, n: int, size: int, red: bool) -> bool:
    return any(all(col[frozenset((a, b))] == red for a, b in combinations(S, 2))
               for S in combinations(range(n), size))


def red_degrees(col: Coloring, n: int) -> List[int]:
    deg = [0] * n
    for a, b in combinations(range(n), 2):
        if col[frozenset((a, b))]:
            deg[a] += 1; deg[b] += 1
    return deg


def main() -> None:
    ladder = circulant(8, [1, 4])  # Mobius ladder C_8(1,4)
    assert not has_mono(ladder, 8, 3, True), "ladder must be red-triangle-free"
    assert not has_mono(ladder, 8, 4, False), "ladder complement must be K4-free"
    print("Lower bound: C_8(1,4) avoids (3,4) -> R(3,4) > 8")
    print("  red-degree sequence:", red_degrees(ladder, 8))
    # Upper bound: a 9-vertex counterexample is forced 3-regular; 9*3 = 27 is odd.
    print("Upper bound: forced 3-regular on 9 vertices => degree sum 27 (odd),")
    print("  contradicting the handshake lemma => 9 -> (3,4). Hence R(3,4) = 9.")


if __name__ == "__main__":
    main()

"""First-moment lower bound: certified R_r(k,k) > n whenever 2*C(n,k) < 2^C(k,r)."""
from math import comb
from typing import Tuple


def first_moment_lower_bound(k: int, r: int = 2) -> int:
    threshold = 2 ** comb(k, r)
    n = k
    while 2 * comb(n + 1, k) < threshold:
        n += 1
    return n


def compare_sqrt2(k: int) -> Tuple[int, int]:
    return first_moment_lower_bound(k, 2), 2 ** (k // 2)


def main() -> None:
    print("graph case r=2:  R(k,k) > certified-n   vs   2^(k/2)")
    for k in [4, 6, 8, 10, 12, 16, 20]:
        n, h = compare_sqrt2(k)
        print(f"  k={k:2d}: R(k,k) > {n:7d}   (2^(k/2) = {h})")
    print("higher uniformity r at k=8:")
    for r in [2, 3, 4]:
        print(f"  r={r}: R_{r}(8,8) > {first_moment_lower_bound(8, r)}")


if __name__ == "__main__":
    main()

